use super::*;
use crate::engine_runtime::ShutdownKind;
use mudmaker_engine_wire::{pb,mudmaker::scripting::v1 as shared,Policy};
fn start(managed:&Arc<Managed>)->Status{match managed.begin(Locator::Development).unwrap(){Start::Ready(s)=>s,Start::Launch(t)=>t.run().unwrap()}}
fn call(m:&Managed,r:RequestDto)->Response{m.admit(r).unwrap().wait().unwrap()}
fn entity()->Entity{Entity{world_id:"00112233-4455-6677-8899-aabbccddeeff".into(),index:u32::MAX-1,generation:u32::MAX}}
fn id()->String{"dea816fc-0ae4-4eac-b02a-a1596450f93a".into()}
fn field(m:&Managed,e:&Entity,value:Value)->Response{call(m,RequestDto::Field{entity:e.clone(),component_type_id:"efbeba2d-21cd-4df8-a757-d96e53f8380c".into(),schema_revision:1,field_id:id(),value})}
#[test]
fn actual_managed_owner_start_once_native_operations_and_quit(){
 assert!(std::env::var_os("MUDMAKER_ENGINE_TEST_EXE").is_some());let m=Arc::new(Managed::default());assert_eq!(m.status().state,"stopped");let ticket=match m.begin(Locator::Development).unwrap(){Start::Launch(t)=>t,_=>panic!("initial start")};assert_eq!(m.status().state,"starting");assert!(matches!(m.begin(Locator::Development),Err(Failure{code,..})if code=="busy"));let ready=ticket.run().unwrap();assert_eq!(ready.state,"ready");assert_eq!(start(&m),ready);
 let created=call(&m,RequestDto::Create{components:vec![Component{component_type_id:"efbeba2d-21cd-4df8-a757-d96e53f8380c".into(),schema_revision:1,value:Value::Record{fields:vec![]}}]});let e=match created{Response::Created{entity}=>entity,_=>panic!("actual create")};assert_eq!(Some(&e.world_id),ready.world_id.as_ref());assert!(matches!(field(&m,&e,Value::Text{value:"Managed native World".into()}),Response::Mutation{..}));let before=call(&m,RequestDto::Inspect{entity:e.clone()});
 match field(&m,&e,Value::Integer{value:"7".into()}){Response::Error{native_code,entity,field_path,..}=>{assert_eq!(native_code,"world.schema/schema.wrong_type");assert_eq!(entity,Some(e.clone()));assert_eq!(field_path[0],id());},_=>panic!("native error")};assert_eq!(call(&m,RequestDto::Inspect{entity:e}),before);assert_eq!(m.status().state,"ready");m.shutdown(ShutdownMode::Graceful);assert_eq!(m.status().state,"stopped");m.shutdown(ShutdownMode::Immediate);
}
#[test]
fn lossless_values_and_diagnostic_json_roundtrip(){
 let values=vec![Value::Null,Value::Boolean{value:true},Value::Integer{value:i64::MIN.to_string()},Value::Integer{value:i64::MAX.to_string()},Value::Floating{value:1.25},Value::Text{value:"owned".into()},Value::Entity{value:entity()},Value::Asset{value:Asset{asset_guid:id(),revision:u32::MAX}},Value::Record{fields:vec![FieldValue{field_id:id(),value:Value::Null}]},Value::List{items:vec![Value::Integer{value:"9007199254740993".into()}]}];
 for value in values{let json=serde_json::to_string(&value).unwrap();assert_eq!(serde_json::from_str::<Value>(&json).unwrap(),value);let dto=RequestDto::Field{entity:entity(),component_type_id:id(),schema_revision:1,field_id:id(),value};dto::request(dto,Policy::load().unwrap()).unwrap();}
 let error=Response::Error{code:"worldFailure".into(),native_code:"world.schema/schema.wrong_type".into(),message:"Wrong type.".into(),world_id:Some(entity().world_id),entity:Some(entity()),component_type_id:Some(id()),schema_revision:Some(u32::MAX),field_path:vec![id(),"profile.name".into()]};let json=serde_json::to_string(&error).unwrap();assert_eq!(serde_json::from_str::<Response>(&json).unwrap(),error);
}
#[test]
fn flat_metadata_presence_and_all_constraint_sizes_are_lossless(){
 let scalar=|n:i64|pb::EngineValue{value:Some(pb::engine_value::Value::Primitive(shared::PropertyValue{value:Some(shared::property_value::Value::IntegerValue(n))}))};
 let body=pb::envelope::Body::CatalogResult(pb::CatalogResult{total:u64::MAX,next_offset:Some(u64::MAX-1),schemas:vec![pb::ComponentSchemaInfo{component_type_id:id(),schema_revision:1,name:"creator.metadata".into(),persistence:pb::Persistence::Persistent as i32,placement:pb::Placement::Sparse as i32,display:"Metadata".into(),description:"Actual metadata shape".into(),fields:vec![pb::FieldInfo{field_id:id(),name:"absent".into(),required:false,type_id:1,display:String::new(),description:String::new(),default_value:None},pb::FieldInfo{field_id:entity().world_id,name:"null".into(),required:false,type_id:1,display:String::new(),description:String::new(),default_value:Some(pb::EngineValue{value:Some(pb::engine_value::Value::Primitive(shared::PropertyValue{value:Some(shared::property_value::Value::ExplicitNull(true))}))})}],types:(1..=8).map(|kind|pb::TypeInfo{type_id:kind as u32,kind,nullable:true,element_type_id:if kind==8{1}else{0},fields:vec![],constraints:Some(pb::Constraints{integer_min:Some(i64::MIN),integer_max:Some(i64::MAX),floating_min:Some(-1.25),floating_max:Some(1.25),text_min_bytes:Some(0),text_max_bytes:Some(u64::MAX),list_min_items:Some(0),list_max_items:Some(u64::MAX),enum_values:vec![scalar(i64::MIN),scalar(i64::MAX)]})}).collect()}]});
 let result=dto::response(body,Policy::load().unwrap()).unwrap();let json=serde_json::to_value(&result).unwrap();assert_eq!(json["total"],u64::MAX.to_string());assert!(json["schemas"][0]["fields"][0].get("defaultValue").is_none());assert_eq!(json["schemas"][0]["fields"][1]["defaultValue"]["kind"],"null");assert_eq!(json["schemas"][0]["types"][0]["constraints"]["integerMin"],i64::MIN.to_string());assert_eq!(json["schemas"][0]["types"][0]["constraints"]["textMaxBytes"],u64::MAX.to_string());assert_eq!(serde_json::from_value::<Response>(json).unwrap(),result);
}
#[test]
fn invalid_numbers_and_preconversion_budgets_never_admit(){
 assert!(serde_json::from_str::<Value>(r#"{"kind":"integer","value":9007199254740993}"#).is_err());assert!(serde_json::from_str::<Value>(r#"{"kind":"other","value":1}"#).is_err());
 for n in ["+1","01","-0","9223372036854775808","1e2"]{assert!(dto::request(RequestDto::Field{entity:entity(),component_type_id:id(),schema_revision:1,field_id:id(),value:Value::Integer{value:n.into()}},Policy::load().unwrap()).is_err());}
 assert!(dto::request(RequestDto::Catalog{offset:"18446744073709551616".into(),limit:1},Policy::load().unwrap()).is_err());let mut p=Policy::load().unwrap();p.value_nodes=2;assert!(dto::request(RequestDto::Create{components:vec![Component{component_type_id:id(),schema_revision:1,value:Value::Record{fields:vec![FieldValue{field_id:id(),value:Value::List{items:vec![Value::Null,Value::Null]}}]}}]},p).is_err());let mut v=Value::Null;for _ in 0..33{v=Value::List{items:vec![v]};}assert!(dto::request(RequestDto::Field{entity:entity(),component_type_id:id(),schema_revision:1,field_id:id(),value:v},Policy::load().unwrap()).is_err());assert!(dto::request(RequestDto::Field{entity:entity(),component_type_id:id(),schema_revision:1,field_id:id(),value:Value::Floating{value:f64::NAN}},Policy::load().unwrap()).is_err());
}
#[test]
fn managed_admission_death_explicit_retry_and_invalidated_start(){
 let cancelled=Arc::new(Managed::default());let ticket=match cancelled.begin(Locator::Development).unwrap(){Start::Launch(t)=>t,_=>unreachable!()};cancelled.shutdown(ShutdownMode::Immediate);assert_eq!(ticket.run().unwrap_err().code,"engine_start_cancelled");assert_eq!(cancelled.status().state,"stopped");
 let m=Arc::new(Managed::default());let first=start(&m);let pending=m.admit(RequestDto::Catalog{offset:"0".into(),limit:1}).unwrap();assert!(matches!(m.admit(RequestDto::List{offset:"0".into(),limit:1}),Err(Failure{code,..})if code=="busy"));pending.wait().unwrap();
 use windows::Win32::{Foundation::*,System::Threading::*};use std::os::windows::io::{FromRawHandle,OwnedHandle};let pid=m.state.lock().unwrap().owner.as_ref().unwrap().status().child_pid;let process=unsafe{OpenProcess(PROCESS_TERMINATE|PROCESS_SYNCHRONIZE,false,pid)}.unwrap();let owned=unsafe{OwnedHandle::from_raw_handle(process.0)};unsafe{TerminateProcess(process,ERROR_PROCESS_ABORTED.0)}.unwrap();assert_eq!(unsafe{WaitForSingleObject(process,5000)},WAIT_OBJECT_0);assert_eq!(m.status().state,"failed");assert!(m.status().world_id.is_none());let retry=start(&m);assert_ne!(first.world_id,retry.world_id);drop(owned);m.shutdown(ShutdownMode::Graceful);let _=ShutdownKind::Graceful;
}
